<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
type Tab = 'beranda' | 'obat' | 'kontrol' | 'profil'
const activeTab = ref<Tab>('beranda'), reporting = ref(false), cameraError = ref(''), locationText = ref('Lokasi belum diambil'), stream = ref<MediaStream | null>(null), video = ref<HTMLVideoElement | null>(null), photo = ref<string | null>(null), medicationTaken = ref(true), reason = ref(''), sideEffect = ref(false), sideEffectDescription = ref('')
const reportReady = computed(() => Boolean(photo.value) && (medicationTaken.value || reason.value.trim()) && (!sideEffect.value || sideEffectDescription.value.trim()))
async function openCamera(): Promise<void> { cameraError.value = ''; try { stream.value = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false }); if (video.value) video.value.srcObject = stream.value; reporting.value = true; navigator.geolocation.getCurrentPosition((p) => { locationText.value = `${p.coords.latitude.toFixed(5)}, ${p.coords.longitude.toFixed(5)} · akurasi ${Math.round(p.coords.accuracy)} m` }, () => { locationText.value = 'Lokasi belum tersedia. Aktifkan izin lokasi untuk melanjutkan.' }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }) } catch { cameraError.value = 'Akses kamera diperlukan untuk membuat laporan minum obat. Aktifkan izin kamera dari pengaturan browser.' } }
function closeStream(): void { stream.value?.getTracks().forEach((track) => track.stop()); stream.value = null }
function capture(): void { if (!video.value) return; const canvas = document.createElement('canvas'); canvas.width = video.value.videoWidth; canvas.height = video.value.videoHeight; canvas.getContext('2d')?.drawImage(video.value, 0, 0); photo.value = canvas.toDataURL('image/jpeg', .85); closeStream() }
function closeReport(): void { closeStream(); reporting.value = false }
function submit(): void { if (!reportReady.value) return; alert('Laporan siap dikirim. API produksi akan memberi waktu server dan watermark.'); closeReport() }
onBeforeUnmount(closeStream)
</script>
<template><main class="phone-shell"><header class="topbar"><div><p class="eyebrow">Selamat pagi,</p><h1>Rina Sari</h1></div><button class="avatar" aria-label="Buka notifikasi">RS<span /></button></header><section v-if="activeTab === 'beranda'" class="page"><article class="hero-card"><p>JADWAL BERIKUTNYA</p><h2>Minum obat pagi</h2><strong>07:00 WIB</strong><span class="pill">Dalam 18 menit</span><button class="primary" @click="openCamera">Ambil Foto &amp; Lapor</button></article><section class="section-heading"><h2>Hari ini</h2><button>15 Sep 2026</button></section><article class="schedule-card"><div class="time">07:00</div><div><h3>Obat pagi</h3><p>Rifampisin · Isoniazid</p></div><span class="status pending">Menunggu</span></article><article class="schedule-card muted"><div class="time">19:00</div><div><h3>Obat malam</h3><p>Sesuai rencana pengobatan</p></div><span class="status">Nanti</span></article><section class="section-heading"><h2>Informasi penting</h2></section><article class="control-card"><div class="calendar">18<br><small>SEP</small></div><div><p>Kontrol berikutnya</p><h3>Jumat, 18 September</h3><span>09:00 · Puskesmas Kebayoran</span></div></article><article class="cadre-card"><div class="cadre-avatar">AP</div><div><p>Kader PMO Anda</p><h3>Ayu Permata</h3><span>Siap membantu kepatuhan obat Anda</span></div><button>Hubungi</button></article></section><section v-else-if="activeTab === 'obat'" class="page centered"><h2>Jadwal Obat</h2><p>Semua jadwal Anda tersimpan aman dan dapat dilaporkan langsung melalui kamera.</p><button class="primary" @click="openCamera">Lapor Minum Obat</button></section><section v-else-if="activeTab === 'kontrol'" class="page centered"><h2>Jadwal Kontrol</h2><p>Jumat, 18 September 2026 · 09:00 WIB</p><button class="secondary">Tambahkan ke Kalender</button></section><section v-else class="page centered"><div class="profile-avatar">RS</div><h2>Rina Sari</h2><p>Profil dan informasi pengobatan Anda dikelola oleh Puskesmas.</p><button class="secondary">Keluar</button></section><nav class="bottom-nav"><button :class="{ active: activeTab === 'beranda' }" @click="activeTab = 'beranda'">● Beranda</button><button :class="{ active: activeTab === 'obat' }" @click="activeTab = 'obat'">✚ Obat</button><button :class="{ active: activeTab === 'kontrol' }" @click="activeTab = 'kontrol'">▣ Kontrol</button><button :class="{ active: activeTab === 'profil' }" @click="activeTab = 'profil'">◉ Profil</button></nav><div v-if="reporting || cameraError" class="modal-backdrop"><section class="report-modal" role="dialog" aria-modal="true"><button class="close" @click="closeReport">×</button><h2>Konfirmasi minum obat</h2><p class="hint">Ambil foto langsung dari kamera. Foto galeri tidak dapat digunakan.</p><p v-if="cameraError" class="error">{{ cameraError }}</p><template v-else><video v-if="!photo" ref="video" autoplay playsinline class="camera-preview" /><img v-else :src="photo" alt="Pratinjau bukti minum obat" class="camera-preview" /><button v-if="!photo" class="capture" @click="capture">Ambil Foto</button><button v-else class="secondary full" @click="photo = null; openCamera()">Ambil Ulang</button><p class="location">⌖ {{ locationText }}</p><fieldset><legend>Apakah sudah minum obat hari ini?</legend><label><input v-model="medicationTaken" :value="true" type="radio"> Ya</label><label><input v-model="medicationTaken" :value="false" type="radio"> Belum</label></fieldset><textarea v-if="!medicationTaken" v-model="reason" placeholder="Apa alasan belum minum obat?" /><fieldset><legend>Apakah ada efek samping?</legend><label><input v-model="sideEffect" :value="false" type="radio"> Tidak ada</label><label><input v-model="sideEffect" :value="true" type="radio"> Ada</label></fieldset><textarea v-if="sideEffect" v-model="sideEffectDescription" placeholder="Jelaskan efek samping yang dirasakan" /><button class="primary full" :disabled="!reportReady" @click="submit">Kirim laporan</button></template></section></div></main></template>
